"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[523],{3321(e){e.exports=JSON.parse('{"title":"\ud3f0\ud2b8\uc758 \uacfc\uac70, \ud604\uc7ac, \uadf8\ub9ac\uace0 \ubbf8\ub798","date":"2025-09-02","coverUrl":null,"html":"<p data-notion-block-id=\\"262e548d-8a8e-8053-a4da-f6c9bb62446b\\">9\uc6d4 4\uc77c \uc774\ud6c4 \ud6c8\ub828\uc18c\uc5d0 \ub4e4\uc5b4\uac00\uac8c \ub418\uc5b4, \ub274\uc2a4\ub808\ud130\ub294 \ud55c\ub2ec\uac04 \uc26c\uac8c \ub429\ub2c8\ub2e4. 10\uc6d4 7\uc77c\uc5d0 \ubd48\uc5b4\uc694!</p><h1 data-notion-block-id=\\"25be548d-8a8e-805c-bdd7-c80dedc69c7c\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"260e548d-8a8e-801f-8db6-ce6e7685627f\\" id=\\"260e548d-8a8e-801f-8db6-ce6e7685627f\\">\ud3f0\ud2b8\uc758 \uacfc\uac70, \ud604\uc7ac, \uadf8\ub9ac\uace0 \ubbf8\ub798</h2><a href=\\"https://www.jonoalderson.com/performance/youre-loading-fonts-wrong/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jonoalderson.com/performance/youre-loading-fonts-wrong/</a><p data-notion-block-id=\\"260e548d-8a8e-80d8-bae8-d6ee67d00e2f\\">\uc6f9 \ud3f0\ud2b8\ub97c \uc124\uc815\ud560 \ub54c \uacfc\uac70\uc640 \ud604\uc7ac, \uadf8\ub9ac\uace0 \ubbf8\ub798\ub294 \uc5b4\ub5bb\uac8c \ub420 \uac83\uc778\uc9c0, \uadf8\ub9ac\uace0 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ucd5c\uc801\ud654\ub97c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud754\ud558\uc9c0 \uc54a\uc740 \uc6a9\uc5b4\uc640 \ub9ce\uc740 \uc804\ub7b5\uae4c\uc9c0 \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ubc88\uc678\ub85c, \uc6f9 \ud3f0\ud2b8 \uc678\uc758 \ub2e4\ub978 \uc885\ub958\ub3c4 \ubcf4\uae38 \uc6d0\ud558\uc2e0\ub2e4\uba74 <a href=\\"https://behdad.org/text2024/\\">2024\ub144 \ud14d\uc2a4\ud2b8 \ub80c\ub354\ub9c1 \ud604\ud669</a> \uae00, \uac04\ub2e8\ud55c \ubc84\uc804\uc758 \ucd5c\uc801\ud654 \ubc29\uc2dd\uc744 \ubcf4\uc2dc\ub824\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/cd29f440-15b4-4145-a8d4-ec9da1e43ce9#21c73feb-f0bb-4e5c-9980-01ba9558a07a\\">\ud3f0\ud2b8 \ucd5c\uc801\ud654\uc758 \ubaa8\ub4e0 \uac83</a>\uc744 \ubcf4\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"25be548d-8a8e-8059-9899-ec326b2bcd80\\" id=\\"25be548d-8a8e-8059-9899-ec326b2bcd80\\"><code>--experimental-transform-types</code>\ub85c monorepo \uc798 \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://blog.calm.com/engineering/how-we-migrated-our-rushjs-monorepo-to-node-type-stripping\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.calm.com/engineering/how-we-migrated-our-rushjs-monorepo-to-node-type-stripping</a><p data-notion-block-id=\\"260e548d-8a8e-803f-9f35-caeee3f83a64\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/17ee548d-8a8e-8045-8a26-f5dfa6d03856#17ee548d-8a8e-8006-ba30-fc20a932c3a8\\">Node.js\uc758 Type Stripping</a>\uc744 \uc774\uc6a9\ud574\uc11c \ube4c\ub4dc \uc2dc\uac04\uc744 \ub2e8\ucd95\ud558\uae30 \uc704\ud574 ESM \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc5b4\ub5bb\uac8c \ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube4c\ub4dc \ub3c4\uad6c\uc744 \uc774\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74, \uadf8\ub9ac\uace0 tsc\ub85c \uc778\ud55c \ube4c\ub4dc\uc2dc\uac04\uc774 \ub290\ub9ac\ub2e4\uba74, \uace0\ub824\ud574\ubcfc\ub9cc\ud558\uaca0\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"260e548d-8a8e-8073-ac7a-f12c76382d8a\\" id=\\"260e548d-8a8e-8073-ac7a-f12c76382d8a\\"><code>semver</code> \ub300\uccb4 \ucf54\ub4dc\ub97c \uc0ac\uc6a9\ud558\uc138\uc694.</h2><a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-12/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-12/</a><p data-notion-block-id=\\"260e548d-8a8e-809e-a5f0-f1887c849828\\"><code>semver</code>\uac00 Parse, don\'t validate \uc6d0\uce59\uc774\ub098, \uac1d\uccb4 \uc0dd\uc131, \u2026 \uc5ec\ub7ec\uac00\uc9c0 \ud544\uc694\uc5c6\ub294 \uc131\ub2a5 \ubb38\uc81c\uc810\ub4e4\uc744 \uc9da\uace0, \uc5b4\ub5bb\uac8c \ucee4\uc2a4\ud140 \ub85c\uc9c1\uc73c\ub85c \uc131\ub2a5 \ud5a5\uc0c1\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <code>semver</code>\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uc131\ub2a5 \ubb38\uc81c\uc810\uc740 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc790\uc5d0\uac8c\ub3c4 \uc88b\uc740 \uc9c0\uc810\uc774\ubbc0\ub85c \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \uc774 \ubd84\uc758 \ub2e4\ub978 \uae00\ub4e4\ub3c4\uc694!</p><h1 data-notion-block-id=\\"25be548d-8a8e-805f-8f0c-effb048b3b6c\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"260e548d-8a8e-804f-891a-d140e6abfaf3\\" id=\\"260e548d-8a8e-804f-891a-d140e6abfaf3\\">React\ub294 Git rebase\ub2e4.</h2><a href=\\"https://jordaneldredge.com/notes/react-rebasing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jordaneldredge.com/notes/react-rebasing/</a><p data-notion-block-id=\\"260e548d-8a8e-800b-bdea-cffcf7c58851\\">React\uc758 UI \uc5c5\ub370\uc774\ud2b8 \uacfc\uc815\uc744 Git rebase\uc5d0 \ube57\ub300\uc5b4\uc11c \uc124\uba85\ud558\ub294 \uc7ac\ubc0c\ub294 \uc2dc\uc120\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"260e548d-8a8e-80eb-9911-ff62ad985163\\" id=\\"260e548d-8a8e-80eb-9911-ff62ad985163\\">\uc790\uc5f0\uc2a4\ub7ec\uc6b4 <code>Date()</code>\uc0ac\uc6a9\uc744 \uc704\ud574 Hydration \ub9c9\uc544\ubcf4\uae30</h2><a href=\\"https://ethanniser.dev/blog/a-clock-that-doesnt-snap/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ethanniser.dev/blog/a-clock-that-doesnt-snap/</a><h2 data-notion-block-id=\\"25be548d-8a8e-80ec-b6a1-ffa3e04e520c\\" id=\\"25be548d-8a8e-80ec-b6a1-ffa3e04e520c\\">Promise\ub780 \ubb34\uc5c7\uc77c\uae4c..</h2><a href=\\"https://www.joshwcomeau.com/javascript/promises/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/javascript/promises/</a><h2 data-notion-block-id=\\"260e548d-8a8e-8096-8caf-d22f26e058c0\\" id=\\"260e548d-8a8e-8096-8caf-d22f26e058c0\\"><code>oklch()</code> \uc774\ud574\ud558\uae30</h2><a href=\\"https://jakub.kr/components/oklch-colors\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakub.kr/components/oklch-colors</a><h2 data-notion-block-id=\\"25de548d-8a8e-804b-bb77-e9a9203a7615\\" id=\\"25de548d-8a8e-804b-bb77-e9a9203a7615\\"><code>napi-rs</code>\ub85c Node.js\uc5d0\uc11c Rust\ucf54\ub4dc \ud638\ucd9c\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://napi.rs/blog/function-and-callbacks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://napi.rs/blog/function-and-callbacks</a><h2 data-notion-block-id=\\"25de548d-8a8e-8041-a4b6-faf75ca08d6a\\" id=\\"25de548d-8a8e-8041-a4b6-faf75ca08d6a\\">Best practice\ub9cc\uc774 \uc815\ub2f5\uc774 \uc544\ub2c8\ub2e4.</h2><a href=\\"https://www.craigabbott.co.uk/blog/best-practice-is-just-your-opinion/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.craigabbott.co.uk/blog/best-practice-is-just-your-opinion/</a><p data-notion-block-id=\\"262e548d-8a8e-8029-9dff-c1b3eae26c7e\\">\uc811\uadfc\uc131\uc5d0\uc11c Best practice\ub77c\uace0 \uc5ec\uae30\ub294 WCAG\uac00 \uc815\ub2f5\uc774 \uc544\ub2c8\ub2e4\ub77c\uace0 \ub9d0\ud574\uc8fc\ub294 \uae00\uc774\uc9c0\ub9cc, \ub9ce\uc740 \uacf3\uc5d0 \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"25be548d-8a8e-80f5-ac13-eb9faf109d9f\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://rspack.rs/blog/announcing-1-5\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rspack.rs/blog/announcing-1-5</a><p data-notion-block-id=\\"25be548d-8a8e-8041-b284-c4a081dd837a\\">\uc8fc\ubaa9\ud560\ub9cc\ud55c \uae30\ub2a5\uc778 Barrel file optimization\uc774 \ub098\uc628 Rspack 1.5 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://socket.dev/blog/eslint-adds-support-for-parallel-linting\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/eslint-adds-support-for-parallel-linting</a><p data-notion-block-id=\\"260e548d-8a8e-80ea-844f-f6c1cca14624\\">ESLint\uc5d0 \ubcd1\ub82c \ub9b0\ud2b8\uac00 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://colinhacks.com/essays/introducing-zod-codecs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://colinhacks.com/essays/introducing-zod-codecs</a><p data-notion-block-id=\\"260e548d-8a8e-809a-86da-e00868131c5e\\">zod\uc758 \uc0c8\ub85c\uc6b4 API\uac00 \ub4f1\uc7a5\ud588\uc2b5\ub2c8\ub2e4. zod\uac00 \uac00\uc7a5 \ud45c\uc900\uc774\ub77c\uace0 \ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4\uace0 \uc0dd\uac01\ud558\ubbc0\ub85c, \uc8fc\ubaa9\ud560\ub9cc \ud558\ub124\uc694.</p><h3 data-notion-block-id=\\"25de548d-8a8e-807d-9238-fe4ff9bcfa05\\">\ubc88\uc678: Big O \ud45c\uae30\ubc95 \uc778\ud130\ub809\ud2f0\ube0c\ud558\uac8c \uc774\ud574\ud558\uae30</h3><a href=\\"https://samwho.dev/big-o/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://samwho.dev/big-o/</a>"}')}}]);